@@ -0,0 +1,36 @@
+import { VoiceBroadcastRecording } from './VoiceBroadcastRecording';
+import { TypedEventEmitter } from 'matrix-js-sdk/src/models/typed-event-emitter';
+
+interface Events {
+    [VoiceBroadcastRecordingsStoreEvent.RecordingAdded]: (recording: VoiceBroadcastRecording) => void;
+    [VoiceBroadcastRecordingsStoreEvent.RecordingUpdated]: (recording: VoiceBroadcastRecording) => void;
+}
+
+export enum VoiceBroadcastRecordingsStoreEvent {
+    RecordingAdded = 'recording_added',
+    RecordingUpdated = 'recording_updated',
+}
+
+export class VoiceBroadcastRecordingsStore extends TypedEventEmitter<Events> {
+    private recordings: Map<string, VoiceBroadcastRecording> = new Map();
+
+    public addRecording(recording: VoiceBroadcastRecording): void {
+        this.recordings.set(recording.getId(), recording);
+        this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingAdded, recording);
+    }
+
+    public updateRecording(recording: VoiceBroadcastRecording): void {
+        if (this.recordings.has(recording.getId())) {
+            this.recordings.set(recording.getId(), recording);
+            this.emit(VoiceBroadcastRecordingsStoreEvent.RecordingUpdated, recording);
+        }
+    }
+
+    public getRecording(id: string): VoiceBroadcastRecording | undefined {
+        return this.recordings.get(id);
+    }
+
+    public getAllRecordings(): VoiceBroadcastRecording[] {
+        return Array.from(this.recordings.values());
+    }
+}
