+import { VoiceBroadcastRecording } from '../VoiceBroadcastRecording';
+import { VoiceBroadcastRecordingsStore } from '../VoiceBroadcastRecordingsStore';
+import { VoiceBroadcastInfoState } from '../index';
+
+export function startNewVoiceBroadcastRecording(store: VoiceBroadcastRecordingsStore, id: string, chunkLength: number, relatesTo?: { rel_type: string; event_id: string }): VoiceBroadcastRecording {
+    const recording = new VoiceBroadcastRecording(id, VoiceBroadcastInfoState.Started, chunkLength, relatesTo);
+    store.addRecording(recording);
+    return recording;
+}

